<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import TraceIcon from '@/components/trace/TraceIcon.vue'
import EvaluationChart from '@/components/trace/EvaluationChart.vue'
import { evaluationStore, setEvaluationDataset, resetEvaluationFilters } from '@/trace/evaluation-store'
import { parseEvaluationFile, filterRuns, summarizeRuns, modelSummaries, datasetWarnings, findings, exportSummaryCsv } from '@/trace/evaluation-data.mjs'
import { createEvaluationDemo } from '@/trace/evaluation-demo.mjs'
import { heatmapOption, boxplotOption, scatterOption, modelColor, TASK_SYMBOLS } from '@/trace/evaluation-charts.mjs'
import { validTraceRunId } from '@/trace/trace-client.mjs'
import { formatDuration, formatValue, statusLabel } from '@/trace/trace-data.mjs'

const router = useRouter(), fileInput = ref(null), error = ref(''), busy = ref(false)
const page = ref(1), pageSize = 10, selectedKey = ref(''), sort = ref('default'), showRules = ref(false)
const dataset = computed(() => evaluationStore.dataset)
const allRuns = computed(() => dataset.value?.runs || [])
const filters = evaluationStore.filters
const models = computed(() => [...new Set(allRuns.value.map((run) => run.modelLabel))].sort())
const tasks = computed(() => [...new Map(allRuns.value.map((run) => [run.taskId, { id: run.taskId, name: run.taskName }])).values()])
const conditions = computed(() => [...new Set(allRuns.value.map((run) => run.conditionId))])
const filtered = computed(() => filterRuns(allRuns.value, filters))
const summary = computed(() => summarizeRuns(filtered.value))
const modelRows = computed(() => modelSummaries(filtered.value))
const warnings = computed(() => datasetWarnings(filtered.value))
const observation = computed(() => findings(filtered.value))
const sorted = computed(() => {
  const runs = [...filtered.value]
  if (sort.value === 'slowest') runs.sort((a, b) => (b.durationMs ?? -1) - (a.durationMs ?? -1))
  else if (sort.value === 'tokens') runs.sort((a, b) => (b.totalTokens ?? -1) - (a.totalTokens ?? -1))
  else if (sort.value === 'errors') runs.sort((a, b) => Number(b.hasError) - Number(a.hasError))
  return runs
})
const pages = computed(() => Math.max(1, Math.ceil(sorted.value.length / pageSize)))
const pageRows = computed(() => sorted.value.slice((page.value - 1) * pageSize, page.value * pageSize))
const selected = computed(() => allRuns.value.find((run) => run.key === selectedKey.value))
const heatmap = computed(() => heatmapOption(filtered.value))
const boxplot = computed(() => boxplotOption(filtered.value, models.value))
const scatter = computed(() => scatterOption(filtered.value, models.value, tasks.value.map((task) => task.id)))
const scatterCount = computed(() => filtered.value.filter((run) => run.durationMs != null && run.usageComplete && run.totalTokens != null).length)
const ratio = (value) => value == null ? '未评测' : `${(value * 100).toFixed(1)}%`
const correctness = (run) => run.correct == null ? '未评测' : run.correct ? '正确' : '不正确'
const symbolText = (index) => ({ circle: '●', diamond: '◆', triangle: '▲', rect: '■', roundRect: '▰', pin: '▼' }[TASK_SYMBOLS[index % TASK_SYMBOLS.length]])
const previousTitle = document.title
document.title = '模型对比 · Tianmu Trace Studio'
onBeforeUnmount(() => { document.title = previousTitle })
watch(() => JSON.stringify(filters), () => { page.value = 1; selectedKey.value = '' })
watch(() => dataset.value, () => { page.value = 1; selectedKey.value = ''; error.value = '' })
function toggleFilter(key, value) {
  filters[key] = filters[key].includes(value) ? filters[key].filter((item) => item !== value) : [...filters[key], value]
}
function chartSelection(event) {
  if (event.data?.run) openRun(event.data.run)
  else if (event.data?.model) {
    filters.models = [event.data.model]
    if (event.data.taskId) filters.tasks = [event.data.taskId]
  }
}
function openRun(run) {
  selectedKey.value = run.key
  if (run.trace) router.push({ path: '/trace', query: { evaluationRun: run.key } })
  else if (validTraceRunId(run.runId) && !run.demo) router.push({ path: '/trace', query: { runId: run.runId } })
}
async function importDataset(event) {
  const file = event.target.files?.[0]
  if (!file) return
  error.value = ''
  busy.value = true
  try {
    if (file.size > 30 * 1024 * 1024) throw new Error('单文件超过 30 MB，请按实验批次拆分。')
    setEvaluationDataset(parseEvaluationFile(await file.text(), file.name))
  } catch (failure) { error.value = failure.message }
  finally { busy.value = false; event.target.value = '' }
}
function loadDemo() { setEvaluationDataset(parseEvaluationFile(JSON.stringify(createEvaluationDemo()), '内置合成演示')) }
function download(content, filename, type) {
  const url = URL.createObjectURL(new Blob([content], { type }))
  const link = document.createElement('a'); link.href = url; link.download = filename; link.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
function downloadTemplate() {
  download(JSON.stringify({ schemaVersion: 'tianmu-evaluation/1', title: '请替换为实际实验批次', demo: false, runs: [{
    runId: '请替换为实际运行ID', taskId: 'metric-query', taskName: '指标查询', model: '请填写模型名称', modelVersion: '请填写版本',
    conditionId: '请填写相同提示、工具和预算的条件编号', status: 'UNKNOWN', durationMs: null, totalTokens: null, usageComplete: false,
    toolCalls: null, evaluation: { correct: null, basis: '请填写人工标注或数据库对账规则' }, trace: { spans: [], details: {} },
  }] }, null, 2), 'tianmu-evaluation-template.json', 'application/json')
}
</script>

<template>
  <div class="comparison-studio">
    <header class="comparison-topbar">
      <router-link to="/analysis" class="comparison-brand"><span><TraceIcon name="trace" :size="21" /></span><strong>天幕 <small>TIANMU</small></strong></router-link>
      <span class="brand-rule" /><span class="studio-label">Trace Studio</span>
      <nav aria-label="分析导航"><router-link to="/analysis" class="active">模型对比</router-link><router-link to="/trace">运行追踪</router-link></nav>
      <span class="scenario-label">SCENARIO C</span>
    </header>
    <main class="comparison-main">
      <section class="comparison-heading">
        <div><div class="analysis-eyebrow">MODEL COMPARISON <span>/</span> EXPERIMENT EXPLORER</div><h1>模型对比总览<span>从整体差异，追踪到每一次执行。</span></h1></div>
        <div class="page-actions"><button type="button" class="subtle-button" @click="downloadTemplate"><TraceIcon name="download" :size="14" />数据模板</button><button type="button" class="primary-button" :disabled="busy" @click="fileInput.click()"><TraceIcon name="upload" :size="15" />{{ busy ? '正在读取…' : '导入评测数据' }}</button><input ref="fileInput" type="file" accept=".json,.jsonl,application/json" aria-label="导入评测文件" hidden @change="importDataset" /></div>
      </section>
      <div v-if="error" class="analysis-error" role="alert">{{ error }}</div>
      <div class="dataset-banner" :class="{ demo: dataset?.demo }">
        <span class="dataset-dot" /><strong>{{ dataset ? dataset.title : '尚未载入实验数据' }}</strong><span class="dataset-provenance">{{ dataset ? dataset.demo ? '合成演示 · 不作为实验结论' : '导入 / 会话数据 · 请核实采集来源' : '支持评测 JSON 与 Tianmu JSONL' }}</span>
        <div><button type="button" @click="loadDemo">{{ dataset?.demo ? '重新加载演示' : '查看交互演示' }}</button><button v-if="dataset" type="button" @click="setEvaluationDataset(null)">清空数据</button></div>
      </div>

      <section class="analysis-panel filter-panel" aria-label="实验筛选">
        <div class="filter-title"><TraceIcon name="filter" :size="16" /><h2>实验筛选</h2><span>{{ filtered.length }} / {{ allRuns.length }} 次运行</span><button type="button" @click="resetEvaluationFilters">重置筛选</button></div>
        <div class="filter-chip-row"><span class="filter-label">模型</span><div class="filter-chips"><button type="button" :class="{ active: !filters.models.length }" :aria-pressed="!filters.models.length" @click="filters.models = []">全部模型</button><button v-for="model in models" :key="model" type="button" :class="{ active: filters.models.includes(model) }" :aria-pressed="filters.models.includes(model)" @click="toggleFilter('models', model)"><i :style="{ background: modelColor(model, models) }" />{{ model }}</button></div></div>
        <div class="filter-chip-row"><span class="filter-label">任务</span><div class="filter-chips"><button type="button" :class="{ active: !filters.tasks.length }" :aria-pressed="!filters.tasks.length" @click="filters.tasks = []">全部任务</button><button v-for="task in tasks" :key="task.id" type="button" :class="{ active: filters.tasks.includes(task.id) }" :aria-pressed="filters.tasks.includes(task.id)" @click="toggleFilter('tasks', task.id)">{{ task.name }}</button></div></div>
        <div class="filter-fields"><label>实验条件<select v-model="filters.condition" aria-label="实验条件筛选"><option value="">全部条件</option><option v-for="condition in conditions" :key="condition" :value="condition">{{ condition }}</option></select></label><label>运行状态<select v-model="filters.status" aria-label="运行状态筛选"><option value="">全部状态</option><option value="SUCCEEDED">执行成功</option><option value="FAILED">执行失败</option><option value="TIMED_OUT">超时</option><option value="CANCELLED">已取消</option><option value="NEEDS_INPUT">待补充</option><option value="RUNNING">运行中</option><option value="UNKNOWN">未知</option></select></label><label>回答评测<select v-model="filters.verdict" aria-label="回答评测筛选"><option value="">全部评测</option><option value="correct">正确</option><option value="incorrect">不正确</option><option value="unrated">未评测</option></select></label><label class="run-search">查找运行<input v-model="filters.search" aria-label="搜索运行" placeholder="运行 ID、模型、任务或错误类型" /></label></div>
      </section>

      <section class="metric-cards" aria-label="当前筛选统计">
        <article><span><TraceIcon name="list" :size="15" />运行样本</span><strong data-testid="metric-run-count">{{ summary.count }}</strong><small>{{ summary.models.length }} 个模型 · {{ summary.tasks.length }} 类任务</small></article>
        <article><span><TraceIcon name="check" :size="15" />已评测正确率</span><strong data-testid="metric-accuracy">{{ ratio(summary.accuracy) }}</strong><small>正确 {{ summary.correct }} / 已评测 {{ summary.evaluated }}，未评测 {{ summary.count - summary.evaluated }}</small></article>
        <article><span><TraceIcon name="clock" :size="15" />耗时中位数</span><strong>{{ summary.medianMs == null ? '未提供' : (summary.medianMs / 1000).toFixed(2) }}<em v-if="summary.medianMs != null">s</em></strong><small>有耗时 {{ summary.durationCount }} 次 · P95 {{ formatDuration(summary.p95Ms) }}</small></article>
        <article><span><TraceIcon name="token" :size="15" />平均完整 Token</span><strong>{{ summary.meanTokens == null ? '未提供' : Math.round(summary.meanTokens).toLocaleString() }}</strong><small>完整用量 {{ summary.tokenCount }} / {{ summary.count }} 次 · 缺失不记为 0</small></article>
      </section>

      <div v-if="warnings.length" class="data-warnings"><TraceIcon name="info" :size="16" /><div><p v-for="warning in warnings" :key="warning">{{ warning }}</p></div></div>
      <div v-if="!dataset" class="analysis-panel welcome-panel"><TraceIcon name="compare" :size="34" /><div><h2>把模型差异放在同一张图里</h2><p>导入同一批任务的多模型运行记录，查看正确率、延迟和资源差异，再进入单次运行检查执行证据。</p><div><button class="primary-button" type="button" @click="fileInput.click()">导入实验数据</button><button class="subtle-button" type="button" @click="loadDemo">体验 3 模型 × 3 任务演示<TraceIcon name="arrow" :size="14" /></button></div></div></div>
      <div v-else-if="!filtered.length" class="analysis-panel welcome-panel"><TraceIcon name="filter" :size="30" /><div><h2>没有符合条件的运行</h2><p>调整模型、任务、评测状态或搜索条件，所有图表与统计会同步更新。</p><button class="subtle-button" type="button" @click="resetEvaluationFilters">清除筛选</button></div></div>

      <template v-if="filtered.length">
        <section class="chart-grid">
          <article class="analysis-panel chart-card"><div class="chart-heading"><div><span class="chart-index">01</span><h2>模型 × 任务正确率</h2></div><span>点击单元格筛选</span></div><EvaluationChart :option="heatmap" label="模型与任务的已评测正确率热力图，点击单元格筛选对应模型和任务" @select="chartSelection" /><p class="chart-footnote">颜色表示正确率，n 为已评测数量；灰色表示没有评测标签。</p></article>
          <article class="analysis-panel chart-card"><div class="chart-heading"><div><span class="chart-index">02</span><h2>各模型耗时分布</h2></div><span>点击散点进入运行</span></div><EvaluationChart :option="boxplot" label="各模型端到端耗时箱线图，单位秒；散点表示单次运行" @select="chartSelection" /><p class="chart-footnote">箱体为 Q1–Q3，线为中位数，须在 1.5×IQR 内。n&lt;5 时仅作描述。</p></article>
          <article class="analysis-panel chart-card scatter-card"><div class="chart-heading"><div><span class="chart-index">03</span><h2>耗时与 Token 的关系</h2></div><span>{{ scatterCount }} 次完整样本 · 点击进入详情</span></div><EvaluationChart :option="scatter" label="耗时与完整 Token 散点图：颜色为模型，形状为任务，点大小为工具调用次数" @select="chartSelection" /><div class="scatter-legend"><span v-for="model in summary.models" :key="model"><i :style="{ background: modelColor(model, models) }" />{{ model }}</span><span class="legend-divider" /><span v-for="task in tasks.filter(task => summary.tasks.includes(task.id))" :key="task.id"><b>{{ symbolText(tasks.findIndex(item => item.id === task.id)) }}</b>{{ task.name }}</span></div><p class="chart-footnote">颜色＝模型 · 形状＝任务 · 点大小＝工具次数（最多映射 12 次）· 粉色边框＝评测不正确。缺少完整用量的运行不绘制。</p><p v-if="!scatterCount" class="chart-missing">当前没有完整耗时与 Token 数据，请在运行列表中核查缺失值。</p></article>
        </section>

        <section class="analysis-panel model-summary"><div class="section-heading"><h2>模型指标对照</h2><span>同一筛选范围 · 各指标标注实际样本量</span></div><div class="analysis-table-scroll"><table><thead><tr><th>模型</th><th>运行数</th><th>已评测正确率</th><th>耗时中位数 / s</th><th>平均完整 Token</th><th>平均工具次数</th><th>执行成功率</th></tr></thead><tbody><tr v-for="model in modelRows" :key="model.model"><td><button class="model-filter-button" type="button" @click="filters.models = [model.model]"><i :style="{ background: modelColor(model.model, models) }" />{{ model.model }}</button></td><td>{{ model.count }}</td><td>{{ ratio(model.accuracy) }}<small>n={{ model.evaluated }}</small></td><td>{{ model.medianMs == null ? '未提供' : (model.medianMs / 1000).toFixed(2) }}<small>n={{ model.durationCount }}</small></td><td>{{ model.meanTokens == null ? '未提供' : Math.round(model.meanTokens) }}<small>n={{ model.tokenCount }}</small></td><td>{{ model.meanTools?.toFixed(1) ?? '未提供' }}</td><td>{{ model.executionRate == null ? '未知' : ratio(model.executionRate) }}</td></tr></tbody></table></div><p class="chart-footnote">执行成功仅指程序终态；回答正确率仅使用明确评测标签，两者独立统计。</p></section>

        <section class="analysis-panel run-section"><div class="section-heading"><div><h2>逐次运行记录 <span>{{ filtered.length }}</span></h2><p>选择一条运行核对评测依据，或打开调用图追踪执行过程。</p></div><div class="run-actions"><select v-model="sort" aria-label="运行排序"><option value="default">原始顺序</option><option value="slowest">耗时从高到低</option><option value="tokens">Token 从高到低</option><option value="errors">错误运行优先</option></select><button class="subtle-button" type="button" @click="download(exportSummaryCsv(filtered), 'tianmu-evaluation-filtered.csv', 'text/csv;charset=utf-8')"><TraceIcon name="download" :size="13" />导出筛选结果</button></div></div>
          <div class="analysis-table-scroll"><table class="runs-table"><thead><tr><th>运行 ID / 任务</th><th>模型</th><th>运行状态</th><th>回答评测</th><th>耗时</th><th>Token</th><th>工具</th><th>联动</th></tr></thead><tbody><tr v-for="run in pageRows" :key="run.key" :class="{ selected: selectedKey === run.key }"><td><button type="button" class="run-id-button" @click="selectedKey = run.key">{{ run.runId }}<small>{{ run.taskName }}</small></button></td><td><span class="model-cell"><i :style="{ background: modelColor(run.modelLabel, models) }" />{{ run.modelLabel }}</span></td><td><span class="execution-badge" :class="run.status.toLowerCase()">{{ statusLabel(run.status) }}</span></td><td><span :class="{ 'verdict-correct': run.correct === true, 'verdict-wrong': run.correct === false }">{{ correctness(run) }}</span></td><td>{{ formatDuration(run.durationMs) }}</td><td>{{ formatValue(run.totalTokens) }}<small v-if="run.totalTokens != null && !run.usageComplete" class="partial-label">部分 / 未知</small></td><td>{{ run.toolCalls ?? '—' }}</td><td><button type="button" class="detail-link" :disabled="!run.trace && (!validTraceRunId(run.runId) || run.demo)" :aria-label="`查看运行 ${run.runId} 的调用详情`" @click="openRun(run)">{{ run.trace ? '调用详情' : validTraceRunId(run.runId) && !run.demo ? '后端追踪' : '无 Trace' }}<TraceIcon v-if="run.trace || validTraceRunId(run.runId)" name="arrow" :size="13" /></button></td></tr></tbody></table></div>
          <div class="pagination"><span>第 {{ page }} / {{ pages }} 页 · 每页 {{ pageSize }} 条</span><div><button type="button" :disabled="page <= 1" @click="page--">上一页</button><button type="button" :disabled="page >= pages" @click="page++">下一页</button></div></div>
          <div v-if="selected" class="selected-run-card"><div><span class="analysis-eyebrow">SELECTED RUN</span><h3>{{ selected.runId }}</h3><p>{{ selected.taskName }} · {{ selected.modelLabel }} · {{ selected.conditionId }}</p></div><div><span>评测依据</span><p>{{ selected.basis || '未记录；请在实验数据中补充 evaluation.basis。' }}</p><span>错误类型</span><p>{{ selected.errorType || '未标注错误类型' }}</p></div><button class="subtle-button" type="button" :disabled="!selected.trace && !validTraceRunId(selected.runId)" @click="openRun(selected)">打开运行详情<TraceIcon name="arrow" :size="14" /></button></div>
        </section>

        <section class="analysis-panel observation-panel"><div class="section-heading"><h2>数据观察与核查线索</h2><span>{{ dataset.demo ? '演示提示，不是实验发现' : '基于当前筛选的描述性统计，需人工解释' }}</span></div><div class="observation-grid"><article v-for="(finding, index) in observation" :key="finding.title"><span class="observation-number">0{{ index + 1 }}</span><div><h3>{{ finding.title }}</h3><p>{{ finding.text }}</p><button v-if="finding.runKey" type="button" @click="openRun(allRuns.find(run => run.key === finding.runKey))">核查这次运行<TraceIcon name="arrow" :size="12" /></button></div></article></div></section>
      </template>

      <section class="analysis-panel methodology"><button type="button" :aria-expanded="showRules" @click="showRules = !showRules"><TraceIcon name="info" :size="15" /><span>数据口径与复现说明</span><TraceIcon name="down" :size="14" /></button><div v-if="showRules" class="methodology-content"><p>正确率＝正确运行数 / 有布尔型评测标签的运行数；执行成功率＝SUCCEEDED / 已进入终态的运行数。未评测和缺失值均不填零。</p><p>所有时间统一为 ms 存储、s 绘图。Token 平均值和散点图仅使用 usageComplete=true 的完整用量。工具次数按 tool_call 节点计数，read_skill 子阶段不重复累加。</p><p>条件编号应用于统一提示词、工具权限、输入及预算。筛选不同任务和条件可能改变结果；小样本差异不推断因果。模型版本未给出时无法确认版本可比性。</p><p>导入文件只留在当前标签页内存，不上传、不写入浏览器存储。刷新或身份变化会清空数据。导出的 CSV 仅含运行级指标，不含节点正文；完整日志请保留在你们的私有实验材料中。</p></div></section>
      <footer class="analysis-footer"><span><i />Tianmu Trace Studio · 场景 C 多模型分析</span><span>筛选 → 对比 → 核查运行 → 查看节点证据</span></footer>
    </main>
  </div>
</template>

<style>
html.analysis-workspace-page,html.analysis-workspace-page body{min-width:0;background:#0b111b}html.analysis-workspace-page #app{max-width:none;background:#0b111b}
